const body = pm.response.json();

pm.test("El servidor responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("El backend reporta estado UP", function () {
    pm.expect(body.status).to.eql("UP");
});

pm.test("Está conectado a la base petcare_db", function () {
    pm.expect(body.database).to.eql("petcare_db");
});

pm.test("Incluye los contadores de usuarios y mascotas", function () {
    pm.expect(body).to.have.property("usersCount");
    pm.expect(body).to.have.property("petsCount");
});

pm.test("Responde en menos de 1 segundo", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});
